type DishSeed = {
  name: string;
  price: number;
  description?: string;
  /** Shown in What's cooking? on the homepage (needs a photo). */
  featured?: boolean;
  /** Has a photo in /assets/v2/dishes without being featured. */
  photo?: boolean;
  /** Photo file name when it differs from the dish slug. */
  photoName?: string;
  /** Leads What's cooking? on the homepage. */
  lead?: boolean;
  dietary?: string[];
  imageAlt?: string;
};

const slugify = (value: string) =>
  value
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

/**
 * Marked vegetarian from the ingredients each menu entry lists (the printed
 * menus carry no veg marks). Staff can change any of these in /admin.
 */
const VEGETARIAN = new Set([
  "Benne Dosa",
  "Mushroom / Paneer Ghee Roast Benne Dosa",
  "Mushroom / Paneer Chettinad Benne Dosa",
  "Ulundu Bonda",
  "Clay Pot Tatte Idli",
  "Butter Podi Clay Pot Tatte Idli",
  "Herbed Garlic Butter Clay Pot Tatte Idli",
  "Ghee Shallow Fried",
  "Appe Masala",
  "South Indian Breakfast",
  "Udupi Uppit",
  "Sheera",
  "Chimichurri Bowl",
  "Sweet Potato Chickpeas Buddha Bowl",
  "Fajita Buddha Bowl",
  "Miso Mushroom Buddha Bowl",
  "Mixed Sprouts Buddha Bowl",
  "Yogurt Muesli Bowl",
  "Paneer",
  "Tofu",
]);

function dishes(category: string, items: DishSeed[]): Dish[] {
  return items.map((item, i) => {
    const slug = slugify(item.name);
    const hasPhoto = Boolean(item.featured || item.photo);
    return {
      id: `dish-${slug}`,
      slug,
      name: item.name,
      description: item.description ?? "",
      price: item.price,
      category,
      origin: "",
      influence: "",
      ingredients: [],
      technique: "",
      story: "",
      image: hasPhoto ? `/assets/v2/dishes/${item.photoName ?? slug}.webp` : "",
      imageAlt: hasPhoto ? (item.imageAlt ?? item.name) : "",
      gallery: [],
      dietary: item.dietary ?? (VEGETARIAN.has(item.name) ? ["Vegetarian"] : []),
      spiceLevel: 0,
      chefRecommendation: Boolean(item.lead),
      isNew: false,
      soldOut: false,
      pairing: "",
      featured: Boolean(item.featured),
      published: true,
      sort: i + 1,
      updatedAt: "",
    };
  });
}

